-- 0020_growth_foundation.sql
create schema if not exists growth;
create table if not exists growth.reviews(id uuid primary key default gen_random_uuid(),customer_id uuid not null references customer.customers(id),product_id uuid not null references catalog.products(id),order_item_id uuid references commerce.order_items(id),rating int not null check(rating between 1 and 5),title text,body text,status text not null default 'pending' check(status in ('pending','published','rejected')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists growth_review_order_item_uq on growth.reviews(customer_id,order_item_id) where order_item_id is not null;
create table if not exists growth.referrals(id uuid primary key default gen_random_uuid(),referrer_customer_id uuid not null references customer.customers(id),code text unique not null,status text not null default 'active' check(status in ('active','disabled')),created_at timestamptz not null default now());
create table if not exists growth.referral_events(id uuid primary key default gen_random_uuid(),referral_id uuid not null references growth.referrals(id),referred_customer_id uuid references customer.customers(id),order_id uuid references commerce.orders(id),event_type text not null check(event_type in ('signup','qualified_order','rewarded','reversed')),created_at timestamptz not null default now());
create table if not exists growth.bundles(id uuid primary key default gen_random_uuid(),code text unique not null,name_ar text,name_en text,status text not null default 'draft' check(status in ('draft','active','archived')),created_at timestamptz not null default now());
create table if not exists growth.bundle_items(id uuid primary key default gen_random_uuid(),bundle_id uuid not null references growth.bundles(id) on delete cascade,product_variant_id uuid not null references catalog.product_variants(id),quantity numeric not null check(quantity>0),unique(bundle_id,product_variant_id));
alter table growth.reviews enable row level security; alter table growth.referrals enable row level security; alter table growth.referral_events enable row level security; alter table growth.bundles enable row level security; alter table growth.bundle_items enable row level security;
create policy growth_reviews_read on growth.reviews for select to authenticated using(status='published' or customer_id=(select c.id from customer.customers c where c.auth_user_id=auth.uid()) or platform.has_permission(auth.uid(),'orders.manage'));
create policy growth_reviews_create on growth.reviews for insert to authenticated with check(customer_id=(select c.id from customer.customers c where c.auth_user_id=auth.uid()));
create policy growth_reviews_manage on growth.reviews for update to authenticated using(platform.has_permission(auth.uid(),'orders.manage')) with check(platform.has_permission(auth.uid(),'orders.manage'));
create policy growth_referrals_read on growth.referrals for select to authenticated using(referrer_customer_id=(select c.id from customer.customers c where c.auth_user_id=auth.uid()) or platform.has_permission(auth.uid(),'orders.manage'));
create policy growth_bundles_read on growth.bundles for select to authenticated using(status='active' or platform.has_permission(auth.uid(),'orders.manage'));
create policy growth_bundle_items_read on growth.bundle_items for select to authenticated using(exists(select 1 from growth.bundles b where b.id=bundle_items.bundle_id and (b.status='active' or platform.has_permission(auth.uid(),'orders.manage'))));
create or replace function growth.submit_review(p_product_id uuid,p_order_item_id uuid,p_rating int,p_title text default null,p_body text default null) returns growth.reviews language plpgsql security definer set search_path=growth,commerce,customer,catalog,public as $$ declare c customer.customers;oi commerce.order_items;r growth.reviews;begin if auth.uid() is null then raise exception 'UNAUTHENTICATED';end if;select * into c from customer.customers where auth_user_id=auth.uid();if not found then raise exception 'CUSTOMER_NOT_FOUND';end if;select * into oi from commerce.order_items where id=p_order_item_id and order_id in(select id from commerce.orders where customer_id=c.id) and product_id=p_product_id;if not found then raise exception 'REVIEW_ORDER_ITEM_INVALID';end if;if not exists(select 1 from commerce.orders where id=oi.order_id and status='delivered') then raise exception 'REVIEW_NOT_ELIGIBLE';end if;insert into growth.reviews(customer_id,product_id,order_item_id,rating,title,body) values(c.id,p_product_id,p_order_item_id,p_rating,p_title,p_body) returning * into r;return r;end;$$;
revoke all on function growth.submit_review(uuid,uuid,int,text,text) from public;grant execute on function growth.submit_review(uuid,uuid,int,text,text) to authenticated;
create or replace function growth.create_referral_code(p_code text) returns growth.referrals language plpgsql security definer set search_path=growth,customer,public as $$ declare c customer.customers;r growth.referrals;begin select * into c from customer.customers where auth_user_id=auth.uid();if not found then raise exception 'CUSTOMER_NOT_FOUND';end if;if nullif(trim(p_code),'') is null then raise exception 'INVALID_CODE';end if;insert into growth.referrals(referrer_customer_id,code) values(c.id,upper(trim(p_code))) returning * into r;return r;end;$$;
revoke all on function growth.create_referral_code(text) from public;grant execute on function growth.create_referral_code(text) to authenticated;
create or replace function marketing.record_attribution_event(p_session_key text,p_event_type text,p_source text default null,p_medium text default null,p_campaign text default null,p_content text default null,p_landing_page text default null,p_payload jsonb default '{}') returns marketing.attribution_events language plpgsql security definer set search_path=marketing,customer,public as $$ declare c customer.customers;e marketing.attribution_events;begin select * into c from customer.customers where auth_user_id=auth.uid();insert into marketing.attribution_events(customer_id,session_key,event_type,source,medium,campaign,content,landing_page,payload) values(c.id,p_session_key,p_event_type,p_source,p_medium,p_campaign,p_content,p_landing_page,coalesce(p_payload,'{}')) returning * into e;return e;end;$$;
revoke all on function marketing.record_attribution_event(text,text,text,text,text,text,text,jsonb) from public;grant execute on function marketing.record_attribution_event(text,text,text,text,text,text,text,jsonb) to authenticated;